#include <iostream>
#include <vector>
#include <string>

int main() {
    std::vector<int> leftBrackets;
    std::vector<int> rightBrackets;
    int totalPairs;
    std::cin >> totalPairs;
    std::string inputStr;
    std::cin >> inputStr;

    for (int i = 0; i < totalPairs; i++) {
        if (inputStr[i] == '(') {
            leftBrackets.push_back(i);
        } else if (inputStr[i] == ')') {
            rightBrackets.push_back(i);
        }
    }

    int totalWordsCount = 0;
    auto getSegments = [&](const std::string& s, const std::vector<int>& starts, const std::vector<int>& ends) {
        std::vector<std::string> segments;
        for (size_t i = 0; i < starts.size(); i++) {
            segments.push_back(s.substr(starts[i] + 1, ends[i] - starts[i] - 1));
        }
        return segments;
    };

    for (const auto& segment : getSegments(inputStr, leftBrackets, rightBrackets)) {
        size_t start = 0;
        size_t end = 0;
        size_t pos = 0;
        while (pos != std::string::npos) {
            pos = segment.find('_', start);
            std::string part;
            if (pos == std::string::npos) {
                part = segment.substr(start);
            } else {
                part = segment.substr(start, pos - start);
            }
            if (!part.empty()) {
                totalWordsCount++;
            }
            start = pos + 1;
        }
    }

    int maxLengthWord = 0;
    leftBrackets.push_back(inputStr.length());
    rightBrackets.insert(rightBrackets.begin(), 0);
    int startIdx = (inputStr[0] == '(') ? 1 : 0;

    for (size_t i = startIdx; i < rightBrackets.size(); i++) {
        std::string segment;
        if (inputStr[rightBrackets[i]] == ')') {
            segment = inputStr.substr(rightBrackets[i] + 1, leftBrackets[i] - rightBrackets[i] - 1);
        } else {
            segment = inputStr.substr(rightBrackets[i], leftBrackets[i] - rightBrackets[i]);
        }
        size_t start = 0;
        size_t pos = 0;
        while (pos != std::string::npos) {
            pos = segment.find('_', start);
            std::string part;
            if (pos == std::string::npos) {
                part = segment.substr(start);
            } else {
                part = segment.substr(start, pos - start);
            }
            if (part.length() > maxLengthWord && part.find('(') == std::string::npos && part.find(')') == std::string::npos) {
                maxLengthWord = part.length();
            }
            start = pos + 1;
        }
    }

    std::cout << maxLengthWord << " " << totalWordsCount << std::endl;
    return 0;
}

